# Databricks notebook source
# DBTITLE 1,Bronze Ingestion - Parker Hannifin Components
# Bronze Ingestion Layer — Parker Hannifin Component Maintenance Pipeline
#
# Ingests five source tables generated by the Parker Hannifin Data Simulator:
#   - bronze_customer_registry   : Parker’s 10 airline customers
#   - bronze_aircraft_registry   : 328 aircraft across all customer fleets
#   - bronze_components_registry : 1,640 Parker components installed on aircraft
#   - bronze_maintenance_records : 9,839 historical maintenance logs
#   - bronze_component_telemetry : 1,640 current component health readings
#
# All tables live in genie_zeroops_mfg_catalog.default (written by the simulator).

from pyspark import pipelines as dp
from pyspark.sql import functions as F

SOURCE = "genie_zeroops_mfg_catalog.default"


# ── Customer Registry ──────────────────────────────────────────────────────

@dp.materialized_view(
    name="bronze_customer_registry",
    comment="Parker Hannifin’s 10 airline customers: name, hub, and fleet size.",
)
@dp.expect("valid_airline", "airline IS NOT NULL")
def bronze_customer_registry():
    return spark.read.table(f"{SOURCE}.bronze_customer_registry")


# ── Aircraft Registry ───────────────────────────────────────────────────────

@dp.materialized_view(
    name="bronze_aircraft_registry",
    comment="Fleet registry: 328 aircraft (tail number, type, airline, age, hours).",
)
@dp.expect_all_or_drop({
    "valid_tail": "tail_number IS NOT NULL",
    "valid_airline": "airline IS NOT NULL",
})
def bronze_aircraft_registry():
    return spark.read.table(f"{SOURCE}.bronze_aircraft_registry")


# ── Components Registry ───────────────────────────────────────────────────

@dp.materialized_view(
    name="bronze_components_registry",
    comment="1,640 Parker components (5 types) installed across the fleet. PK: component_id.",
)
@dp.expect_all_or_drop({
    "valid_component": "component_id IS NOT NULL",
    "valid_type":      "component_type IS NOT NULL",
    "valid_cycles":    "cycles_since_install >= 0",
})
def bronze_components_registry():
    return spark.read.table(f"{SOURCE}.bronze_components_registry")


# ── Maintenance Records (streaming append) ───────────────────────────────

@dp.table(
    name="bronze_maintenance_records",
    comment="9,839 maintenance logs over 18 months. 9.8% anomalous. PK: record_id.",
)
@dp.expect_all_or_drop({
    "valid_record":    "record_id IS NOT NULL",
    "valid_component": "component_id IS NOT NULL",
    "valid_date":      "maintenance_date IS NOT NULL",
})
def bronze_maintenance_records():
    return spark.readStream.table(f"{SOURCE}.bronze_maintenance_records")


# ── Component Telemetry (latest health snapshot) ────────────────────────

@dp.materialized_view(
    name="bronze_component_telemetry",
    comment="Current health reading per component: health_index, risk category, warranty exposure.",
)
@dp.expect_all_or_drop({
    "valid_component":  "component_id IS NOT NULL",
    "valid_health":     "health_index BETWEEN 0 AND 100",
    "valid_risk":       "failure_risk_category IN ('LOW','MEDIUM','HIGH','CRITICAL')",
})
def bronze_component_telemetry():
    return spark.read.table(f"{SOURCE}.bronze_component_telemetry")

# ---------------------------------------------------------------------------
# Streaming: Raw Flight Telemetry
# ---------------------------------------------------------------------------


@dp.table(
    name="bronze_raw_telemetry",
    comment="Raw flight telemetry streamed from the simulator",
)
@dp.expect_all_or_drop(
    {
        "valid_timestamp": "timestamp IS NOT NULL",
        "valid_flight_id": "flight_id IS NOT NULL",
        "valid_altitude": "altitude >= 0",
        "valid_oil_pressure_eng1": "oil_pressure_eng1 >= 0",
        "valid_oil_pressure_eng2": "oil_pressure_eng2 >= 0",
    }
)
def bronze_raw_telemetry():
    return spark.readStream.table(f"{SOURCE_SCHEMA}.raw_flight_telemetry")


# ---------------------------------------------------------------------------
# Streaming: API / Zerobus Staging Telemetry
# ---------------------------------------------------------------------------


@dp.table(
    name="bronze_staging_telemetry",
    comment="API/Zerobus-ingested telemetry records from staging",
)
@dp.expect_all_or_drop(
    {
        "valid_timestamp": "timestamp IS NOT NULL",
        "valid_flight_id": "flight_id IS NOT NULL",
        "valid_altitude": "altitude >= 0",
        "valid_oil_pressure_eng1": "oil_pressure_eng1 >= 0",
        "valid_oil_pressure_eng2": "oil_pressure_eng2 >= 0",
    }
)
def bronze_staging_telemetry():
    return (
        spark.readStream.table(f"{SOURCE_SCHEMA}.staging_flight_telemetry_api")
        .withColumn("anomaly_type", F.col("anomaly_type").cast("string"))
        .withColumn("anomaly_severity", F.col("anomaly_severity").cast("string"))
    )


# ---------------------------------------------------------------------------
# Batch: Flights Metadata
# ---------------------------------------------------------------------------


@dp.materialized_view(
    name="bronze_flights_metadata",
    comment="Flight-level metadata snapshot (one row per flight)",
)
@dp.expect("valid_flight_id", "flight_id IS NOT NULL")
def bronze_flights_metadata():
    return spark.read.table(f"{SOURCE_SCHEMA}.flights_metadata")


# ---------------------------------------------------------------------------
# Batch: Aircraft Registry
# ---------------------------------------------------------------------------


@dp.materialized_view(
    name="bronze_aircraft_registry",
    comment="Aircraft fleet registry snapshot (one row per tail number)",
)
@dp.expect("valid_tail_number", "tail_number IS NOT NULL")
def bronze_aircraft_registry():
    return spark.read.table(f"{SOURCE_SCHEMA}.aircraft_registry")